import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

/**
 * GarageRepairs - หน้ารายการซ่อม
 * 
 * Features:
 * 1. แสดงรายการซ่อมที่ได้รับจากบริษัทประกันภัย
 * 2. อัพเดตสถานะการซ่อม
 * 3. ขออนุมัติรายการเพิ่มเติม
 * 
 * TODO: Backend Integration
 * - GET /api/garage/repairs?status={status}
 * - PUT /api/garage/repairs/{id}/status
 * - POST /api/garage/repairs/{id}/request-approval
 */
const GarageRepairs = () => {
  const [loading, setLoading] = useState(true);
  const [repairs, setRepairs] = useState([]);
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  const statusFilters = [
    { value: 'all', label: 'ทั้งหมด', icon: 'filter_list' },
    { value: 'pending', label: 'รอยืนยัน', icon: 'pending', color: 'warning' },
    { value: 'in_progress', label: 'กำลังซ่อม', icon: 'build', color: 'info' },
    { value: 'waiting_parts', label: 'รออะไหล่', icon: 'inventory_2', color: 'secondary' },
  ];

  useEffect(() => {
    // Mock data
    setTimeout(() => {
      setRepairs([
        {
          id: '1',
          claimNumber: 'CLM-2024-001',
          status: 'pending',
          
          customerName: 'นายสมชาย ใจดี',
          customerPhone: '081-234-5678',
          
          vehicle: {
            brand: 'Honda',
            model: 'City',
            year: 2020,
            licensePlate: 'กข 1234 กรุงเทพ',
            color: 'ขาว',
          },
          
          damageDescription: 'ชนด้านหน้า กันชนบุบ ไฟหน้าซ้ายแตก',
          approvedAmount: 25000,
          
          receivedDate: '2024-10-26 09:00',
          estimatedCompletionDate: '2024-10-30',
          
          progress: 0,
        },
        {
          id: '2',
          claimNumber: 'CLM-2024-003',
          status: 'in_progress',
          
          customerName: 'นางสุดา รักษ์ดี',
          customerPhone: '082-345-6789',
          
          vehicle: {
            brand: 'Toyota',
            model: 'Yaris',
            year: 2021,
            licensePlate: 'งง 5678 กรุงเทพ',
            color: 'แดง',
          },
          
          damageDescription: 'ชนด้านหลัง ประตูหลังบุบ',
          approvedAmount: 15000,
          
          receivedDate: '2024-10-24 10:00',
          estimatedCompletionDate: '2024-10-28',
          
          progress: 60,
          currentStep: 'กำลังซ่อมตัวถัง',
        },
        {
          id: '3',
          claimNumber: 'CLM-2024-005',
          status: 'waiting_parts',
          
          customerName: 'นายประเสริฐ มั่นคง',
          customerPhone: '083-456-7890',
          
          vehicle: {
            brand: 'Mazda',
            model: 'CX-5',
            year: 2022,
            licensePlate: 'ฮฮ 9999 กรุงเทพ',
            color: 'น้ำเงิน',
          },
          
          damageDescription: 'ชนด้านข้าง กระจกด้านขวาแตก',
          approvedAmount: 18000,
          
          receivedDate: '2024-10-25 14:00',
          estimatedCompletionDate: '2024-10-29',
          
          progress: 30,
          currentStep: 'รอกระจกจากศูนย์',
        },
      ]);
      setLoading(false);
    }, 500);
  }, []);

  const filteredRepairs = repairs.filter(repair => {
    if (filterStatus !== 'all' && repair.status !== filterStatus) {
      return false;
    }
    
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      return (
        repair.claimNumber.toLowerCase().includes(term) ||
        repair.customerName.toLowerCase().includes(term) ||
        repair.vehicle.licensePlate.toLowerCase().includes(term)
      );
    }
    
    return true;
  });

  const getStatusConfig = (status) => {
    const config = {
      pending: { label: 'รอยืนยัน', color: 'warning', icon: 'pending' },
      in_progress: { label: 'กำลังซ่อม', color: 'info', icon: 'build' },
      waiting_parts: { label: 'รออะไหล่', color: 'secondary', icon: 'inventory_2' },
      completed: { label: 'เสร็จสิ้น', color: 'success', icon: 'check_circle' },
    };
    return config[status] || config.pending;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <span className="material-icons-round animate-spin text-6xl text-secondary-500 mb-4">refresh</span>
          <p className="text-neutral-500">กำลังโหลดข้อมูล...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-neutral-dark mb-2">
          รายการซ่อม
        </h1>
        <p className="text-neutral-500">
          จัดการและอัพเดตสถานะรายการซ่อม - {filteredRepairs.length} รายการ
        </p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="card hover:shadow-card-hover transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-neutral-500 text-sm mb-1">รอยืนยัน</p>
              <h3 className="text-3xl font-bold text-warning">
                {repairs.filter(r => r.status === 'pending').length}
              </h3>
            </div>
            <div className="w-14 h-14 rounded-xl bg-warning/10 text-warning flex items-center justify-center">
              <span className="material-icons-round text-3xl">pending</span>
            </div>
          </div>
        </div>

        <div className="card hover:shadow-card-hover transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-neutral-500 text-sm mb-1">กำลังซ่อม</p>
              <h3 className="text-3xl font-bold text-info">
                {repairs.filter(r => r.status === 'in_progress').length}
              </h3>
            </div>
            <div className="w-14 h-14 rounded-xl bg-info/10 text-info flex items-center justify-center">
              <span className="material-icons-round text-3xl">build</span>
            </div>
          </div>
        </div>

        <div className="card hover:shadow-card-hover transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-neutral-500 text-sm mb-1">รออะไหล่</p>
              <h3 className="text-3xl font-bold text-secondary-600">
                {repairs.filter(r => r.status === 'waiting_parts').length}
              </h3>
            </div>
            <div className="w-14 h-14 rounded-xl bg-secondary-100 text-secondary-600 flex items-center justify-center">
              <span className="material-icons-round text-3xl">inventory_2</span>
            </div>
          </div>
        </div>

        <div className="card hover:shadow-card-hover transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-neutral-500 text-sm mb-1">เสร็จวันนี้</p>
              <h3 className="text-3xl font-bold text-success">3</h3>
            </div>
            <div className="w-14 h-14 rounded-xl bg-success/10 text-success flex items-center justify-center">
              <span className="material-icons-round text-3xl">check_circle</span>
            </div>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="card-static">
        <div className="flex flex-col lg:flex-row gap-4">
          <div className="flex-1">
            <div className="relative">
              <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-neutral-400">
                search
              </span>
              <input
                type="text"
                placeholder="ค้นหาด้วยเลขเคลม, ชื่อลูกค้า, ทะเบียนรถ..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="input-field pl-12"
              />
            </div>
          </div>

          <div className="flex gap-2 overflow-x-auto">
            {statusFilters.map(filter => (
              <button
                key={filter.value}
                onClick={() => setFilterStatus(filter.value)}
                className={`
                  flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm whitespace-nowrap transition-all duration-300
                  ${filterStatus === filter.value
                    ? 'bg-secondary-500 text-white shadow-button'
                    : 'bg-neutral-100 text-neutral-600 hover:bg-neutral-200'
                  }
                `}
              >
                <span className="material-icons-round text-sm">{filter.icon}</span>
                <span>{filter.label}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Repairs List */}
      {filteredRepairs.length === 0 ? (
        <div className="card-static text-center py-16">
          <span className="material-icons-round text-6xl text-neutral-300 mb-4">
            build_circle
          </span>
          <p className="text-neutral-500 text-lg mb-2">
            ไม่มีรายการซ่อม
          </p>
          <p className="text-neutral-400 text-sm">
            {searchTerm ? 'ลองเปลี่ยนคำค้นหา' : 'เมื่อมีรายการใหม่จะแสดงที่นี่'}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {filteredRepairs.map(repair => {
            const statusConfig = getStatusConfig(repair.status);
            
            return (
              <div key={repair.id} className="card hover:shadow-card-hover transition-all duration-300">
                {/* Header */}
                <div className="flex items-start justify-between mb-4">
                  <div className="flex-1">
                    <Link
                      to={`/garage/repairs/${repair.id}`}
                      className="text-lg font-semibold text-primary-600 hover:text-primary-700 mb-2 inline-block"
                    >
                      {repair.claimNumber}
                    </Link>
                    <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-${statusConfig.color}/10`}>
                      <span className={`material-icons-round text-sm text-${statusConfig.color}`}>
                        {statusConfig.icon}
                      </span>
                      <span className={`text-sm font-medium text-${statusConfig.color}`}>
                        {statusConfig.label}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Content */}
                <div className="space-y-3 mb-4">
                  <div className="flex items-center gap-3">
                    <span className="material-icons-round text-neutral-400">person</span>
                    <div className="flex-1">
                      <p className="font-medium text-neutral-dark">{repair.customerName}</p>
                      <p className="text-sm text-neutral-500">{repair.customerPhone}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <span className="material-icons-round text-neutral-400">directions_car</span>
                    <div className="flex-1">
                      <p className="font-medium text-neutral-dark">
                        {repair.vehicle.brand} {repair.vehicle.model} ({repair.vehicle.year})
                      </p>
                      <p className="text-sm text-neutral-500">
                        {repair.vehicle.licensePlate} • {repair.vehicle.color}
                      </p>
                    </div>
                  </div>

                  <div className="p-3 bg-neutral-50 rounded-lg">
                    <p className="text-xs text-neutral-500 mb-1">ความเสียหาย</p>
                    <p className="text-sm text-neutral-dark">{repair.damageDescription}</p>
                  </div>

                  <div className="flex items-center justify-between p-3 bg-primary-50 rounded-lg">
                    <span className="text-sm text-neutral-600">วงเงินอนุมัติ</span>
                    <span className="text-lg font-bold text-primary-600">
                      ฿{repair.approvedAmount.toLocaleString()}
                    </span>
                  </div>
                </div>

                {/* Progress */}
                {repair.progress > 0 && (
                  <div className="mb-4">
                    <div className="flex items-center justify-between text-sm mb-2">
                      <span className="text-neutral-600">ความคืบหน้า</span>
                      <span className="font-semibold text-info">{repair.progress}%</span>
                    </div>
                    <div className="w-full h-2 bg-neutral-200 rounded-full overflow-hidden">
                      <div
                        className="h-full bg-info transition-all duration-500"
                        style={{ width: `${repair.progress}%` }}
                      />
                    </div>
                    {repair.currentStep && (
                      <p className="text-xs text-neutral-500 mt-2">
                        <span className="material-icons-round text-xs align-middle mr-1">info</span>
                        {repair.currentStep}
                      </p>
                    )}
                  </div>
                )}

                {/* Metadata */}
                <div className="pt-4 border-t border-neutral-200 flex items-center justify-between text-xs text-neutral-500 mb-4">
                  <span className="flex items-center gap-1">
                    <span className="material-icons-round text-xs">schedule</span>
                    รับ: {repair.receivedDate}
                  </span>
                  <span className="flex items-center gap-1">
                    <span className="material-icons-round text-xs">event</span>
                    คาดการณ์: {repair.estimatedCompletionDate}
                  </span>
                </div>

                {/* Actions */}
                <div className="flex gap-2">
                  <Link
                    to={`/garage/repairs/${repair.id}`}
                    className="btn-primary flex-1 flex items-center justify-center gap-2"
                  >
                    <span className="material-icons-round text-sm">edit</span>
                    <span>อัพเดตสถานะ</span>
                  </Link>
                  <Link
                    to={`/garage/repairs/${repair.id}`}
                    className="btn-outline flex items-center justify-center gap-2"
                  >
                    <span className="material-icons-round text-sm">visibility</span>
                  </Link>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default GarageRepairs;
